// UpdateOrg changes an organization with f, which may refuse with an error. A change of plan is refused with a SeatError
// (ErrOverSeatLimit) when the new plan allows fewer seats than the organization uses.
func (s *Store) UpdateOrg(id string, f func(*Org) error) (Org, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[id]
	if !ok {
		return Org{}, ErrNotFound
	}
	oldPlan := o.Plan
	if err := f(&o); err != nil {
		return Org{}, err
	}
	o.ID = id
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	if o.Plan != oldPlan {
		if limit, limited := o.Plan.SeatLimit(); limited {
			if used := s.seatsUsed(id); used > limit {
				return Org{}, &SeatError{Kind: ErrOverSeatLimit, Limit: limit, Used: used}
			}
		}
	}
	s.orgs[id] = o
	return o, nil
}

// Seats returns how many seats an organization uses (members and pending invites whose role is not viewer) and its plan's
// limit. limited is false when the plan has none.
func (s *Store) Seats(orgID string) (used, limit int, limited bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	limit, limited = s.orgs[orgID].Plan.SeatLimit()
	return s.seatsUsed(orgID), limit, limited
}

// seatsUsed counts an organization's seats. Viewers are free; an invite holds its seat until it is accepted or revoked.
// The caller holds the lock.
func (s *Store) seatsUsed(orgID string) int {
	n := 0
	for k, m := range s.members {
		if k.org == orgID && m.Role != RoleViewer {
			n++
		}
	}
	for _, inv := range s.invites {
		if inv.OrgID == orgID && inv.Role != RoleViewer && inv.AcceptedAt == nil && inv.RevokedAt == nil {
			n++
		}
	}
	return n
}

// checkSeat returns a SeatError (ErrNoSeat) when the organization has no seat left for one more. The caller holds the lock.
func (s *Store) checkSeat(orgID string) error {
	limit, limited := s.orgs[orgID].Plan.SeatLimit()
	if !limited {
		return nil
	}
	if used := s.seatsUsed(orgID); used >= limit {
		return &SeatError{Kind: ErrNoSeat, Limit: limit, Used: used}
	}
	return nil
}

